+def _dashboard_files():
+    files = sorted(TEMPLATE_DIR.glob("*.html"))
+    if STATIC_DIR.exists():
+        files.extend(sorted(path for path in STATIC_DIR.rglob("*") if path.is_file()))
+    return files
