    ('protected paths', guard),
    ('tests present', tests_present),
    ('syntax', syntax),
    ('install', command('pip install -q -e ' + shlex.quote('.[dev]'))),
    ('skills lint', command('prsec-skills-lint prsec-skills')),
    ('unit tests', command('pytest -q -m ' + shlex.quote(MARK))),
]
